  4→
  5→import * as React from 'react';
  6→import { classNames as cx, type ComponentProps } from '../../../util/componentUtil.ts';
  7→import { mergeCallbacks } from '../../../util/reactUtil.ts';
  8→
  9→import { Link as LinkDefault } from '../../../components/actions/Link/Link.tsx';
 10→import { type IconName, Icon as IconDefault } from '../../../components/graphics/Icon/Icon.tsx';
 11→
 12→import cl from './Nav.module.scss';
 13→
 14→
 15→type NavItemLinkProps = Pick<
 16→  React.ComponentProps<typeof LinkDefault>,
 17→  'children' | 'unstyled' | 'tabIndex' | 'aria-disabled' | 'href' | 'className' | 'onClick'
 18→>;
 19→type NavItemIconProps = Pick<React.ComponentProps<typeof IconDefault>, 'className'> & {
 20→  icon?: undefined | string,
 21→};
 22→
 23→export type NavItemProps<
 24→  LinkProps extends NavItemLinkProps,
 25→  IconProps extends NavItemIconProps,
 26→> = ComponentProps<'li'> & {
 27→  /** Whether this component should be unstyled. */
 28→  unstyled?: undefined | boolean,
 29→  
 30→  /** A custom `Link` component. Optional. */
 31→  Link?: undefined | React.ComponentType<LinkProps>,
 32→  
 33→  /** Additional props to pass to the `Link` component. */
 34→  linkProps?: undefined | LinkProps,
 35→  
 36→  /** The target of the nav item link. */
 37→  href?: undefined | string,
 38→  
 39→  /** An icon to show before the link label. */
 40→  icon?: undefined | IconName,
 41→  
 42→  /** A custom `Icon` component. Optional. */
 43→  Icon?: undefined | React.ComponentType<IconProps>,
 44→  
 45→  /** Additional props to pass to the `Icon` component. */
 46→  iconProps?: undefined | IconProps,
 47→  
 48→  /** The nav item link label. */
 49→  label?: undefined | string,
 50→  
 51→  /** Any additional indicators to be shown after the label. */
 52→  indicators?: undefined | React.ReactNode,
 53→  
 54→  /** Whether this nav item is the currently active one. Default: false. */
 55→  active?: undefined | boolean,
 56→  
 57→  /** Whether this nav item should be disabled. Default: false. */
 58→  disabled?: undefined | boolean,
 59→};
 60→export const NavItem = <
 61→  LinkProps extends NavItemLinkProps,
 62→  IconProps extends NavItemIconProps,
 63→>(props: NavItemProps<LinkProps, IconProps>) => {
 64→  const {
 65→    children,
 66→    unstyled,
 67→    className,
 68→    Link = LinkDefault,
 69→    linkProps = {} as LinkProps,
 70→    href,
 71→    icon,
 72→    Icon = IconDefault,
 73→    iconProps = {} as IconProps,
 74→    label,
 75→    indicators,
 76→    active = false,
 77→    disabled = false,
 78→    ...propsRest
 79→  } = props;
 80→  
 81→  const handleClick = React.useCallback((event: React.MouseEvent<HTMLElement>) => {
 82→    if (disabled) {
 83→      event.preventDefault();
 84→    }
 85→  }, [disabled]);
 86→  
 87→  const renderItem = () => {
 88→    if (label) {
 89→      return (
 90→        <Link
 91→          unstyled
 92→          tabIndex={disabled ? -1 : undefined}
 93→          aria-disabled={disabled ? true : undefined}
 94→          href={href}
 95→          {...linkProps}
 96→          className={cx(
 97→            cl['bk-nav__item__link'],
 98→            { [cl['bk-nav__item__link--disabled']]: disabled },
 99→            linkProps.className,
100→          )}
101→          onClick={mergeCallbacks([linkProps.onClick, handleClick])}
102→        >
103→          {(icon && Icon === IconDefault) &&
104→            <Icon icon={icon} {...iconProps} className={cx(cl['bk-nav__item__link__icon'], iconProps.className)}/>
105→          }
106→          {Icon !== IconDefault &&
107→            // @ts-ignore
108→            <Icon {...iconProps} className={cx(cl['bk-nav__item__link__icon'], iconProps.className)}/>
109→          }
110→          <span className={cx(cl['bk-nav__item__link__label'])}>{label}</span>
111→          {indicators}
112→        </Link>
113→      );
114→    }
115→    return children;
116→  };
117→  
118→  return (
119→    <li
120→      aria-current={active ? 'page' : undefined}
121→      {...propsRest}
122→      className={cx(
