  1→/* Copyright (c) Fortanix, Inc.
  2→|* This Source Code Form is subject to the terms of the Mozilla Public License, v. 2.0. If a copy of
  3→|* the MPL was not distributed with this file, You can obtain one at http://mozilla.org/MPL/2.0/. */
  4→
  5→import * as React from 'react';
  6→import { classNames as cx, type ComponentProps } from '../../../../util/componentUtil.ts';
  7→
  8→import { FieldSet } from '../../common/FieldSet/FieldSet.tsx';
  9→import { Radio } from '../Radio/Radio.tsx';
 10→
 11→import cl from './RadioGroup.module.scss';
 12→
 13→
 14→/*
 15→References:
 16→- https://developer.mozilla.org/en-US/docs/Web/Accessibility/ARIA/Roles/radiogroup_role
 17→*/
 18→
 19→export { cl as RadioGroupClassNames };
 20→
 21→
 22→export type RadioKey = string;
 23→
 24→export type RadioGroupContext = {
 25→  name?: undefined | RadioKey,
 26→  formId?: undefined | string,
 27→  selectedButton: undefined | RadioKey,
 28→  selectButton: (radioKey: RadioKey) => void,
 29→};
 30→export const RadioGroupContext = React.createContext<null | RadioGroupContext>(null);
 31→export const useRadioGroupContext = () => {
 32→  const context = React.use(RadioGroupContext);
 33→  if (context === null) { throw new Error(`Missing RadioGroupContext provider`); }
 34→  return context;
 35→};
 36→
 37→
 38→export type RadioGroupButtonProps = Omit<React.ComponentProps<typeof Radio.Labeled>, 'checked'> & {
 39→  /** The unique key of this radio button within the radio group. */
 40→  radioKey: RadioKey,
 41→};
 42→export const RadioGroupButton = ({ radioKey, ...propsRest }: RadioGroupButtonProps) => {
 43→  const context = useRadioGroupContext();
 44→  
 45→  const checked: undefined | boolean = typeof context.selectedButton === 'undefined'
 46→    ? undefined // Uncontrolled
 47→    : context.selectedButton === radioKey; // Controlled
 48→  
 49→  const onChange = (event: React.ChangeEvent<HTMLInputElement>) => {
 50→    propsRest.onChange?.(event);
 51→    if (event.target.checked) {
 52→      context.selectButton(radioKey);
 53→    }
 54→  };
 55→  
 56→  return (
 57→    <Radio.Labeled
 58→      // Note: `<fieldset>` also has a `form` attribute, but just setting `form` on  `<fieldset>` does not affect any
 59→      // of the descendant `<input>` elements. See: https://developer.mozilla.org/en-US/docs/Web/HTML/Element/fieldset
 60→      form={context.formId}
 61→      name={context.name}
 62→      value={radioKey}
 63→      onChange={typeof checked === 'undefined' ? undefined : onChange}
 64→      {...propsRest}
 65→      checked={checked} // Do not allow this to be overridden
 66→    />
 67→  );
 68→};
 69→
 70→export type RadioGroupProps = ComponentProps<typeof FieldSet> & {
 71→  /** Whether this component should be unstyled. */
 72→  unstyled?: undefined | boolean,
 73→  
 74→  /** The machine-readable name of the radio group, used for form data. */
 75→  name?: undefined | string,
 76→  
 77→  /** The human-readable label for the radio group. */
 78→  label?: undefined | React.ReactNode,
 79→  
 80→  /** The orientation of the label relative to the radio group. */
 81→  labelOrientation?: ComponentProps<typeof FieldSet>['orientation'],
 82→  
 83→  /** The default button to select. Only relevant for uncontrolled usage (`selected` is `undefined`). */
 84→  defaultSelected?: undefined | RadioKey,
 85→  
 86→  /** The radio button to select. If `undefined`, this component will be considered uncontrolled. */
 87→  selected?: undefined | RadioKey,
 88→  
 89→  /** Event handler which is called when the selected radio button changes. */
 90→  onUpdate?: undefined | ((radioKey: RadioKey) => void),
 91→  
 92→  /** The orientation of the radio buttons, either horizontal or vertical. Default: `"horizontal"`. */
 93→  orientation?: undefined | 'horizontal' | 'vertical',
 94→};
 95→
 96→/**
 97→ * A group of mutually exclusive radio buttons. Only one radio can be selected at any given time.
 98→ */
 99→export const RadioGroup = Object.assign(
100→  (props: RadioGroupProps) => {
101→    const {
102→      unstyled,
103→      children,
104→      form,
105→      name,
106→      label,
107→      labelOrientation,
108→      defaultSelected,
109→      selected,
110→      onUpdate,
111→      orientation = 'horizontal',
112→      ...propsRest
113→    } = props;
114→    
115→    const [selectedButton, setSelectedButton] = React.useState<undefined | RadioKey>(selected ?? defaultSelected);
116→    
117→    React.useEffect(() => {
118→      if (typeof selected !== 'undefined') {
119→        setSelectedButton(selected);
120→      }
121→    }, [selected]);
122→    
123→    const selectButton = React.useCallback((radioKey: RadioKey) => {
124→      setSelectedButton(selectedButton => {
125→        if (radioKey !== selectedButton) {
126→          onUpdate?.(radioKey);
127→          return radioKey;
128→        } else {
129→          return selectedButton;
130→        }
131→      });
132→    }, [onUpdate]);
133→    
134→    const context = React.useMemo<RadioGroupContext>(() => ({
135→      name,
136→      formId: form,
137→      selectedButton,
138→      selectButton,
139→    }), [name, form, selectedButton, selectButton]);
140→    
141→    return (
142→      <RadioGroupContext value={context}>
143→        <FieldSet
144→          legend={label}
145→          orientation={labelOrientation}
146→          role="radiogroup"
147→          {...propsRest}
148→          className={cx(
149→            'bk',
150→            { [cl['bk-radio-group']]: !unstyled },
