import { classNames as cx, type ComponentProps } from '../../../util/componentUtil.ts';
import * as React from 'react';

import { icons } from '../../../assets/icons/_icons.ts';
import cl from './Spinner.module.scss';


export type SpinnerName = keyof typeof icons;
export { cl as SpinnerClassNames };

export type SpinnerProps = React.PropsWithChildren<ComponentProps<'span'> & {
  /**
   * If the spinner should be inline. Optional. Default: false.
   */
  inline?: undefined | boolean,

  /**
   * The size of the spinner, either "small", "medium" or "large". Optional. Default: "small".
   */
  size?: undefined | 'small' | 'medium' | 'large',
}>;
export const Spinner = ({
  inline,
  size = 'small',
  ...props
}: SpinnerProps) => {
  return (
    <span
      {...props}
      className={cx({
        bk: true,
        [cl['bk-spinner']]: true,
        [cl[`bk-spinner--${size}`]]: true,
        [cl['bk-spinner--inline']]: inline,
      }, props.className)}
    />
  );
};

/* Copyright (c) Fortanix, Inc.
|* This Source Code Form is subject to the terms of the Mozilla Public License, v. 2.0. If a copy of the MPL was not
|* distributed with this file, you can obtain one at http://mozilla.org/MPL/2.0/. */

import * as React from 'react';
import { classNames as cx, type ComponentProps } from '../../../util/componentUtil.ts';

import cl from './ProgressBar.module.scss';


export { cl as ProgressBarClassNames };

export type ProgressBarProps = React.PropsWithChildren<ComponentProps<'progress'> & {
  /** Whether this component should be unstyled. */
  unstyled?: undefined | boolean,

  /** The progress, as a percentage ranging from 0 to 100. */
  progress: number,

  /** An optional label, displayed as the progress bar title. */
  label?: undefined | string,

  /** An optional hint text, displayed below the progress bar. */
  hintText?: undefined | string,
}>;
/**
 * A way to display progress to complete a task or the time remaining.
 */
export const ProgressBar = (props: ProgressBarProps) => {
  const {
    unstyled = false,
    progress = 0,
    label = undefined,
    hintText = undefined,
    ...propsRest
  } = props;
  return (
    <div>
      {label && (
        <div className={cl['bk-progress-bar__label']}>{label}</div>
      )}
      <progress
        {...propsRest}
        className={cx(
          'bk',
          { [cl['bk-progress-bar']]: !unstyled },
          propsRest.className,
        )}
        max={100}
        value={progress}
      >
        {progress}%
      </progress>
      {hintText && (
        <div className={cl['bk-progress-bar__hint-text']}>{hintText}</div>
      )}
    </div>
  );
};

/* Copyright (c) Fortanix, Inc.
|* This Source Code Form is subject to the terms of the Mozilla Public License, v. 2.0. If a copy of
|* the MPL was not distributed with this file, You can obtain one at http://mozilla.org/MPL/2.0/. */

import { classNames as cx, type ComponentProps } from '../../../util/componentUtil.ts';
import * as React from 'react';

import { IconButton } from '../../actions/IconButton/IconButton.tsx';

import cl from './Tag.module.scss';


export { cl as TagClassNames };

export type TagProps = Omit<ComponentProps<'div'>, 'content' | 'children'> & {
  /** Whether this component should be unstyled. */
  unstyled?: undefined | boolean,

  /** Some content to be displayed inside the tag. */
  content: React.ReactNode,

  /** Callback to remove the tag. If set, display a close icon, otherwise it is hidden. */
  onRemove?: () => void,
};
/**
 * A tag component.
 */
export const Tag = (props: TagProps) => {
  const {
    unstyled = false,
    content = null,
    onRemove,
    ...propsRest
  } = props;

  return (
    <div
      {...propsRest}
      className={cx(
        'bk',
        { [cl['bk-tag']]: !unstyled },
        propsRest.className,
      )}
    >
      <span className={cl['bk-tag__content']}>{content}</span>
      {onRemove &&
        <IconButton onPress={onRemove} icon="cross" label="Remove tag" className={cl['bk-tag__action']}/>
      }
    </div>
  );
};

/* Copyright (c) Fortanix, Inc.
|* This Source Code Form is subject to the terms of the Mozilla Public License, v. 2.0. If a copy of
|* the MPL was not distributed with this file, You can obtain one at http://mozilla.org/MPL/2.0/. */

import * as React from 'react';
import { classNames as cx, type ComponentProps } from '../../../util/componentUtil.ts';
import { useScroller } from '../../../layouts/util/Scroller.tsx';

import { Icon } from '../../graphics/Icon/Icon.tsx';

import cl from './Disclosure.module.scss';


export { cl as DisclosureClassNames };
export type DisclosureProps = Omit<ComponentProps<'details'>, 'title'> & {
  /** Whether this component should be unstyled. */
  unstyled?: undefined | boolean,

  /** The title of the disclosure. */
  title: React.ReactNode,

  /** Additional props for the <summary> element. */
  summaryProps?: undefined | Omit<ComponentProps<'summary'>, 'children'>,

  /** Additional props for the details content. */
  contentProps?: undefined | Omit<ComponentProps<'div'>, 'children'>,
};
/**
 * A disclosure, i.e. a collapsible container.
 */
export const Disclosure = (props: DisclosureProps) => {
  const { unstyled = false, title, summaryProps = {}, contentProps = {}, children, ...propsRest } = props;

  // Note: we need to apply `overflow-y: auto` dynamically, so do not apply scroller styling here
  const scrollerProps = useScroller({ includeStyling: false });

  /*
  Some notes on accessibility of `<details>`:
  - https://www.scottohara.me/blog/2022/09/12/details-summary.html (2022)
  - https://www.hassellinclusion.com/blog/accessible-accordions-part-2-using-details-summary (2019)
  - https://a11ysupport.io/tech/html/summary_element
  */

  return (
    <details
      {...propsRest}
      className={cx(
        { bk: true },
        { [cl['bk-disclosure']]: !unstyled },
        propsRest.className,
      )}
    >
      <summary {...summaryProps} className={cx(summaryProps.className)}>
        <span className={cl['bk-disclosure__title']}>
          {title}
        </span>
        <Icon icon="caret-down" className={cl['bk-disclosure__collapse-icon']}/>
      </summary>
      <div
        {...scrollerProps}
        {...contentProps}
        className={cx(cl['bk-disclosure__content'], contentProps.className)}
      >
        {children}
      </div>
    </details>
  );
};

