 14→export { cl as BreadcrumbsClassNames };
 15→
 16→/*
 17→References:
 18→- https://www.w3.org/WAI/ARIA/apg/patterns/breadcrumb/examples/breadcrumb
 19→*/
 20→
 21→
 22→type BreadcrumbItemLinkProps = Pick<
 23→  React.ComponentProps<typeof LinkDefault>,
 24→  'children' | 'unstyled' | 'tabIndex' | 'aria-disabled' | 'href' | 'className' | 'onClick'
 25→>;
 26→
 27→type BreadcrumbItemProps<LinkProps extends BreadcrumbItemLinkProps> = ComponentProps<'li'> & {
 28→  /** Whether this component should be unstyled. */
 29→  unstyled?: undefined | boolean,
 30→  
 31→  /** A custom `Link` component. Optional. */
 32→  Link?: undefined | React.ComponentType<LinkProps>,
 33→  
 34→  /** Additional props to pass to the `Link` component. */
 35→  linkProps?: undefined | LinkProps,
 36→  
 37→  /** The target of the breadcrumb item link. */
 38→  href?: undefined | string,
 39→  
 40→  /** The breadcrumb item link label. */
 41→  label?: undefined | string,
 42→  
 43→  /** Whether this breadcrumb item is the currently active one. Default: false. */
 44→  active?: undefined | boolean,
 45→  
 46→  /** Whether this breadcrumb item should be disabled. Default: false. */
 47→  disabled?: undefined | boolean,
 48→};
 49→export const BreadcrumbItem = <LinkProps extends BreadcrumbItemLinkProps>(props: BreadcrumbItemProps<LinkProps>) => {
 50→  const {
 51→    children,
 52→    unstyled,
 53→    className,
 54→    Link = LinkDefault,
 55→    linkProps = {} as LinkProps,
 56→    href,
 57→    label,
 58→    active = false,
 59→    disabled = false,
 60→    ...propsRest
 61→  } = props;
 62→  
 63→  const handleClick = React.useCallback((event: React.MouseEvent<HTMLElement>) => {
 64→    if (disabled) {
 65→      event.preventDefault();
 66→      event.stopPropagation();
 67→    }
 68→  }, [disabled]);
 69→  
 70→  const renderItem = () => {
 71→    if (active) {
 72→      return label;
 73→    }
 74→    
 75→    if (label) {
 76→      return (
 77→        <Link
 78→          tabIndex={disabled ? -1 : undefined}
 79→          aria-disabled={disabled}
 80→          href={href}
 81→          {...linkProps}
 82→          className={cx(
 83→            cl['bk-breadcrumb__item__link'],
 84→            { [cl['bk-breadcrumb__item__link--disabled']]: disabled },
 85→            linkProps.className,
 86→          )}
 87→          onClick={mergeCallbacks([handleClick, disabled ? undefined : linkProps.onClick])}
 88→        >
 89→          {label}
 90→        </Link>
 91→      );
 92→    }
 93→    return children;
 94→  };
 95→  
 96→  return (
 97→    <li
 98→      aria-current={active ? 'page' : undefined}
 99→      {...propsRest}
100→      className={cx(
101→        { [cl['bk-breadcrumb__item']]: !unstyled },
102→        className,
103→      )}
104→    >
105→      {renderItem()}
106→    </li>
107→  );
108→};
109→
110→
111→type BreadcrumbsProps = React.PropsWithChildren<ComponentProps<'nav'> & {
112→  /** Whether this component should be unstyled. */
113→  unstyled?: undefined | boolean,
114→}>;
115→
116→/**
117→ * An ordered set of links forming the path of the current page.
118→ */
119→export const Breadcrumbs = Object.assign(
120→  (props: BreadcrumbsProps) => {
121→    const { children, unstyled = false, ...propsRest } = props;
122→    
123→    return (
124→      <nav
125→        aria-label="Breadcrumbs"
126→        {...propsRest}
127→        className={cx(
128→          'bk',
129→          { [cl['bk-breadcrumbs']]: !unstyled },
130→          propsRest.className,
131→        )}
132→      >
133→        <ol>
134→          {children}
135→        </ol>
136→      </nav>
137→    );
138→  },
139→  {
140→    Item: BreadcrumbItem,
141→  },
142→);
