64→        type="checkbox"
65→        {...propsRest}
66→        className={cx(
67→          'bk',
68→          { [cl['bk-checkbox']]: !unstyled },
69→          propsRest.className,
70→        )}
71→        onChange={mergeCallbacks([props.onChange, handleChange])}
72→      />
73→    );
74→  },
75→  {
76→    Labeled: CheckboxLabeled,
77→  },
78→);
